import{_ as t,a as i,b as r}from"./chunks/ai-create-03.Cig2rYP0.js";import{_ as e,o,c as l,a3 as n}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"AI로 만들기","description":"MiniTavern은 설정된 모델에 설명과 선택적 참고 이미지를 보내 캐릭터 카드를 만듭니다. 미리보기에서 고치고 유지한 뒤 만듭니다.","frontmatter":{"title":"AI로 만들기","description":"MiniTavern은 설정된 모델에 설명과 선택적 참고 이미지를 보내 캐릭터 카드를 만듭니다. 미리보기에서 고치고 유지한 뒤 만듭니다.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"AI로 만들기 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern은 설정된 모델에 설명과 선택적 참고 이미지를 보내 캐릭터 카드를 만듭니다. 미리보기에서 고치고 유지한 뒤 만듭니다."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/manual/ai-create"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/manual/ai-create"}]]},"headers":[],"relativePath":"ko/manual/ai-create.md","filePath":"ko/manual/ai-create.md","lastUpdated":1791861929000}'),s={name:"ko/manual/ai-create.md"};function c(g,a,p,h,d,u){return o(),l("div",null,[...a[0]||(a[0]=[n('<h1 id="ai로-만들기" tabindex="-1">AI로 만들기 <a class="header-anchor" href="#ai로-만들기" aria-label="Permalink to &quot;AI로 만들기&quot;">​</a></h1><p>경로: 하단 <strong>캐릭터 카드</strong> → <strong>만들기 / 가져오기</strong> → <strong>AI로 만들기</strong>.</p><p>먼저 <a href="./model-link">모델 연결</a>을 설정하고 연결 테스트를 통과하세요. 쓸 수 있는 모델이 없으면 생성할 수 없고, 화면이 설정으로 안내합니다.</p><h2 id="단계" tabindex="-1">단계 <a class="header-anchor" href="#단계" aria-label="Permalink to &quot;단계&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="AI로 만들기 입구"><figcaption>1 · 만들기 / 가져오기 → AI로 만들기</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="설명과 참고 이미지"><figcaption>2 · 모델 선택, 설명 작성</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="미리보기 후 캐릭터 만들기"><figcaption>3 · 미리보기 후 만들기</figcaption></figure></div><h2 id="생성" tabindex="-1">생성 <a class="header-anchor" href="#생성" aria-label="Permalink to &quot;생성&quot;">​</a></h2><ol><li><strong>생성 모델</strong>: 이미 설정된 모델 연결 중에서 고릅니다. 기본으로 지정한 연결이 먼저 선택되며, 다른 연결로 바꿀 수 있습니다.</li><li><strong>설명</strong>(필수): 원하는 캐릭터를 한 단락으로 적습니다.</li><li><strong>참고 이미지</strong>(선택): 이미지를 누르면 확대되고, 오른쪽 위 닫기 아이콘으로 뺍니다. 이미지가 있으면 선택한 모델이 이미지를 지원해야 합니다. 지원하지 않으면 모델을 바꾸거나 이미지를 빼세요.</li><li><strong>생성</strong>을 누릅니다. 버튼이 「생성 중」이 되고, 그동안 모델·설명·참고 이미지는 바꿀 수 없습니다.</li></ol><p>참고 이미지는 모델이 인물을 보게 하는 용도입니다. 첫 생성이 성공하면 그 이미지가 <strong>캐릭터 이미지</strong>로 채워집니다. 모델이 새 그림을 그리지는 않습니다. 참고 이미지가 없으면 미리보기에서 직접 이미지를 골라야 만들 수 있습니다.</p><p>생성에 실패하면 안내가 뜹니다. 「상세 보기」에서 이유를 볼 수 있습니다. 생성을 취소하면 실패 안내는 뜨지 않습니다.</p><h2 id="미리보기와-유지" tabindex="-1">미리보기와 유지 <a class="header-anchor" href="#미리보기와-유지" aria-label="Permalink to &quot;미리보기와 유지&quot;">​</a></h2><p>생성이 성공하면 <strong>캐릭터 미리보기</strong>로 들어갑니다. 생성 화면 자체에는 카드 내용이 나오지 않습니다.</p><ul><li>이름, 설명, 태그, 성격, 오프닝, 세계서 등은 바로 고칠 수 있습니다.</li><li>각 AI 항목과 세계서 전체에 <strong>유지</strong>가 있습니다. 켜 두면 다음 생성에서 그 항목은 덮어쓰지 않습니다. 글을 고쳐도 유지는 자동으로 켜지지 않습니다.</li><li><strong>다시 생성</strong>은 먼저 입력창을 엽니다. 고치고 싶은 점을 적거나, 비워 두면 원래 설명으로 다시 생성합니다. 「유지」가 켜진 항목과 세계서는 그대로입니다. 전부 유지 중이면 요청을 보내지 않습니다.</li><li>생성 중에는 「다시 생성」이 로딩으로 바뀌고, 「캐릭터 만들기」는 취소가 됩니다.</li><li><strong>캐릭터 만들기</strong>는 로딩 안내 뒤 완료 안내가 나옵니다. 만들기 전에 이미지, 이름, 설명이 있어야 합니다.</li><li>애니메이션, 영상 등 기존 작품이 원형이면 세계서를 포함할 수 있습니다. 만들면 카드 안에 그 설정이 남고, 채팅에서 쓰는 세계서로도 복사됩니다. 사용법은 <a href="./lorebook">월드북</a>.</li><li>만들기 전에 미리보기를 나가면 이번 초안은 버려지고 생성 화면으로 돌아갑니다. 참고 이미지는 생성 화면에 남습니다.</li></ul><h2 id="관련" tabindex="-1">관련 <a class="header-anchor" href="#관련" aria-label="Permalink to &quot;관련&quot;">​</a></h2><ul><li><a href="./chara-card">캐릭터 카드</a>: 가져오기, 편집, 개채</li><li><a href="./model-link">모델 연결</a>: 생성에 쓸 모델을 먼저 설정</li></ul>',14)])])}const A=e(s,[["render",c]]);export{_ as __pageData,A as default};
